from taf.sbts.oam.coam.admin.interfaces.admin_22r4 import SBTS22R4
from taf.sbts.oam.coam.admin.exceptions import DataNotAvailable
from taf.sbts.oam.coam.admin.utils import raise_value_error, wrap_with_list
from taf.internal.robot_typecasts import to_boolean


class SBTS23R1(SBTS22R4):

    def __init__(self,
                 api_client=None
                 ):
        """
        :param api_client: instance of an AdminApi class
        """
        super(SBTS23R1, self).__init__(api_client)

    def reset_unit(self, dist_name, reset_type='Soft', force_radio_reset=None, timeout=60, detailed_output=False,
                   **kwargs):
        """
        Preform unit reset procedure.

        :param dist_name: Dist name of unit to reset which is runtime view dist name like:
                          /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1/GNSSE_R-1.
        :param str reset_type: can be `Soft`, `Hard` or `Warm`, defaults to `Soft`
        :param bool force_radio_reset: defaults to False
        :param int timeout: Timeout for the operation.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return list: Unit reset status. Example:
                    [{u'id': u'/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1'},
                     {u'confirmationNode': {u'distName': u'/MRBTS-1/RAT-1/URI-1/SESSION-25/RESET_IND-1/ACK-1',
                     u'parameters': {}},
                     u'indicationDistName': u'/MRBTS-1/RAT-1/URI-1/SESSION-25/RESET_IND-1',
                     u'resultNode': {u'distName': u'/MRBTS-1/RAT-1/URI-1/SESSION-25/RESET_IND-1/RESULT-1',
                     u'parameters': {u'status': u'Succeeded'}}}]

                     Or whole dict response if detailed_output is
                     set to True.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-reset.html
        """

        reset_type = reset_type.title()

        parameters = {"id": dist_name, 'resetType': reset_type}
        if force_radio_reset is not None:
            parameters['forceRadioReset'] = force_radio_reset

        parameters = {k: v for k, v in parameters.items() if v is not None}

        response = self._api_client.execute_customer_procedure("reset", parameters, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def reset_cell(self, cell_id, timeout=60, detailed_output=False, **kwargs):
        """
        Cell reset available from 18A.

        :param str cell_id: NRCEL|LNCEL|WNCEL|GNCEL distName
        :param int timeout: (optional) Timeout for the operation. Defaults set to 120s.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :raises DataNotAvailable: Raised if operation is invalid from Node-B side.
        :return Union[list,dict]: reset cell feedback info or whole dict response if detailed_output is set to True.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-reset.html
        """

        parameters = {"id": cell_id}

        response = self._api_client.execute_customer_procedure(
            name='reset',
            parameters=parameters,
            timeout=timeout)
        if response is None:
            raise DataNotAvailable("ResetCell data has not been provided by M-Plane.")
        return response if detailed_output else response.get(self._provided_content.request_message)

    def reset_all_cells(self, technology, timeout=60, detailed_output=False):
        """
        All cells reset available from 18A.

        :param str technology: NR, LTE, WCDMA, GSM or ALL
        :param int timeout: (optional) Timeout for the operation. Defaults set to 120s.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :raises DataNotAvailable: Raised if operation is invalid from Node-B side.
        :return Union[list,dict]: reset all cells feedback info or whole dict response if detailed_output is set to True.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-reset.html
        """

        technology = str(technology).upper()
        if technology not in ("NR", "LTE", "WCDMA", "GSM", "ALL"):
            raise_value_error(param="technology",
                              value=str(technology),
                              subpage="tutorial-reset.html")

        parameters = {"technology": technology}

        response = self._api_client.execute_customer_procedure(
            name='reset',
            parameters=parameters,
            timeout=timeout)
        if response is None:
            raise DataNotAvailable("ResetAllCells data has not been provided by M-Plane.")
        return response if detailed_output else response.get(self._provided_content.request_message)

    def create_external_bsr_package(self, sw_file, ru_variant, bsr_id, bsr_output_package, tapering_profile=None,
                                    custom_beam_set=None, timeout=120):
        """
        Create external BSR package

        :param str sw_file: path to input file
        :param str ru_variant: RU variant
        :param int bsr_id: BSR ID
        :param str bsr_output_package: path to output file
        :param str tapering_profile: tapering profile value (optional)
        :param str custom_beam_set: custom beam set name (optional)
        :param int timeout: timeout for procedure

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-createExternalBSRPackage.html
        """
        parameters = {"ruVariant": ru_variant, "bsrId": bsr_id}
        if tapering_profile:
            parameters["taperingProfile"] = tapering_profile
        if custom_beam_set:
            parameters["customBeamSet"] = custom_beam_set
        return self._api_client.execute_offline_procedure("createExternalBSRPackage", parameters, timeout,
                                                          input_file_name=sw_file,
                                                          output_file_name=bsr_output_package)

    def delete_bsr_file(self, bsr_files, timeout=120):
        """
        Remove BSR files

        :param str bsr_files: BSR files
        :param int timeout: timeout for procedure


        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-bsrFileDelete.html
        """
        bsr_files = wrap_with_list(bsr_files)
        return self._api_client.execute_procedure("bsrFileDelete", {"bsrFiles": bsr_files}, timeout)

    def get_bsr_files(self, timeout=120):
        """
        Return BSR files

        :param int timeout: timeout for procedure

        :return dict: get_bsr_files feedback

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getBSRFiles.html
        """

        return self._api_client.execute_infomodel_request("getBSRFiles", {}, timeout)

    def power_reset(self, reset_with_snapshot=None, wait_for_reconnection=None, timeout=1200, detailed_output=False,
                    **kwargs):
        """
        Power reset procedure introduced in CB007040 feature

        :param bool reset_with_snapshot: reset with snapshot (optional - default value: false)
        :param bool wait_for_reconnection: wait for reconnection (optional - default value: true)
        :param int timeout: timeout for procedure
        :param bool detailed_output: return full request response when True, defaults set to False.

        :return dict: powerReset feedback

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-powerReset.html
        """
        parameters = {}
        if reset_with_snapshot is not None:
            parameters["resetWithSnapshot"] = to_boolean(reset_with_snapshot)
        if wait_for_reconnection is not None:
            parameters["waitForReconnection"] = to_boolean(wait_for_reconnection)
        response = self._api_client.execute_customer_procedure("powerReset", parameters, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def schedule_emergency_reset(self, timeout=60, detailed_output=False):
        """
        Schedule emergency reset

        :param int timeout: timeout for procedure
        :param bool detailed_output: return full request response when True, defaults set to False.

        :return dict: procedure feedback

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-scheduleEmergencyReset.html
        """
        response = self._api_client.execute_customer_procedure("scheduleEmergencyReset", {}, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def configure_netconf_accounts(self, unsecure_ciphering, authentication_method, accounts, timeout=60):
        """
        Configure Netconf accounts.

        :param bool unsecure_ciphering: Mandatory. One of [True, False].
        :param string authentication_method: Mandatory.
         One of: ['NoAuthentication', 'PublicKeyBased','DeactivationOfSSHPublicKeyValidationAtFirstConnection']
        :param list accounts: Mandatory. Array of accounts along with their parameters. Must contain at least one element.
        All of the parameters are mandatory besides 'id' and 'targetDN'. Optional keys should be ommited.
        Created with below template:
        "accounts": <Array for Accounts> [
                {
                    "id": string, <unique id>
                    "targetDN": string <RMOD_A distName>,
                    "defaultNetconfAccount": {
                        "defaultNetconfAccountName": string,
                        "defaultNetconfAccountPwd": string
                    },
                    "authentifierSshServer": {
                        "publicKeySshServerFormat": string,
                        "publicKeySshServerValue": string

                    },
                    "additionalNetconfAccount": {
                        "additionalNetconfAccountName": string,
                        "additionalNetconfAccountPwd": string,
                        "additionalNetconfAccountType": string
                    }
                }
            ]
        :param int timeout: Time to wait for positive procedure result.

        :return: str: Api response.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-configORUNetconfAccount.html
        """
        if authentication_method not in ('NoAuthentication', 'PublicKeyBased', 'DeactivationOfSSHPublicKeyValidationAtFirstConnection'):
            raise_value_error(param="authentication_method",
                              value=str(authentication_method),
                              subpage="tutorial-configORUNetconfAccount.html")

        parameters = {"actUnsecCiph": unsecure_ciphering,
                      "authenticationMethodSshServer": authentication_method,
                      "accounts": accounts}

        return self._api_client.execute_procedure("configORUNetconfAccount", parameters, timeout)

    def schedule_forced_bts_site_reset(self, timeout=60, detailed_output=False):
        """
        Schedule forced bts site reset.

        :param int timeout: timeout for procedure
        :param bool detailed_output: return full request response when True, defaults set to False.

        :return dict: procedure feedback

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-scheduleForcedBtsSiteReset.html
        """
        response = self._api_client.execute_customer_procedure("scheduleForcedBtsSiteReset", {}, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)
